import threading

def reproduce(connect, service) -> str | None:
    # Money rule: accounts without overdraft must never go negative.
    # Race: SELECT balance check then UPDATE without locking -> concurrent
    # withdraws all see sufficient funds and all succeed.
    # Do several tightly-synchronised waves; open connections BEFORE the
    # barrier so connection setup jitter doesn't stagger the race.
    AMOUNT = 100
    N = 32
    WAVES = 6

    for wave_accounts in ([1], [2], [1, 2]):
        for _ in range(WAVES):
            # snapshot balances before wave
            with connect() as c:
                before = {}
                for aid in wave_accounts:
                    r = c.execute("SELECT balance FROM accounts WHERE id = %s", (aid,)).fetchone()
                    before[aid] = r[0] if r else 0
            # one thread per (account, slot) -> concurrent withdraws on same row(s)
            targets = []
            for aid in wave_accounts:
                for _ in range(N // len(wave_accounts)):
                    targets.append(aid)
            n = len(targets)
            barrier = threading.Barrier(n + 1)
            results = [None] * n

            def worker(idx, aid):
                conn = connect()
                try:
                    barrier.wait(timeout=15)
                    try:
                        service.withdraw(conn, aid, AMOUNT)
                        results[idx] = "ok"
                    except service.InsufficientFunds:
                        results[idx] = "rejected"
                    except Exception as e:
                        results[idx] = f"err:{type(e).__name__}"
                except Exception:
                    results[idx] = "barrier-fail"
                finally:
                    try:
                        conn.close()
                    except Exception:
                        try:
                            conn.__exit__(None, None, None)
                        except Exception:
                            pass

            threads = [threading.Thread(target=worker, args=(i, aid)) for i, aid in enumerate(targets)]
            for t in threads:
                t.start()
            try:
                barrier.wait(timeout=15)
            except Exception:
                pass
            for t in threads:
                t.join(timeout=30)

            with connect() as c:
                for aid in wave_accounts:
                    r = c.execute("SELECT balance FROM accounts WHERE id = %s", (aid,)).fetchone()
                    final = r[0] if r else None
                    if final is not None and final < 0:
                        ok = sum(1 for i, a in enumerate(targets) if a == aid and results[i] == "ok")
                        return (
                            f"overdraft violated: account {aid} balance {before[aid]} -> {final} < 0 "
                            f"({ok} withdraws of {AMOUNT} succeeded concurrently)"
                        )
        # after draining waves on these accounts, check again before next set
    # Final sweep: any negative balance is a violation
    with connect() as c:
        rows = c.execute("SELECT id, balance FROM accounts WHERE balance < 0").fetchall()
        if rows:
            return f"overdraft violated: accounts went negative: {rows[:5]}"
    return None
